raw:
{
  "summary": [
    {
      "text": "Фронт давления — это граница между возмущенной и невозмущенной областями пласта.",
      "claims": [
        "c1"
      ]
    },
    {
      "text": "Радиус этого фронта растет со временем, но скорость его продвижения замедляется.",
      "claims": [
        "c2",
        "c3"
      ]
    }
  ],
  "how_it_works": [
    {
      "text": "При отборе жидкости с постоянным забойным давлением создается депрессия.",
      "claims": [
        "c4"
      ]
    },
    {
      "text": "Вокруг скважины формируется возмущенная область, где давление изменилось.",
      "claims": [
        "c5"
      ]
    },
    {
      "text": "Граница этой области называется фронтом давления R(t).",
      "claims": [
        "c6"
      ]
    },
    {
      "text": "За фронтом находится невозмущенная область с исходным давлением.",
      "claims": [
        "c7"
      ]
    },
    {
      "text": "Отношение радиуса фронта к характерному радиусу r_c обозначается как R(t)/r_c.",
      "claims": [
        "c8"
      ]
    },
    {
      "text": "Время в процессе безразмерное и умножается на параметр fo.",
      "claims": [
        "c9"
      ]
    },
    {
      "text": "Зависимость R(t)/r_c от безразмерного времени показана на графике.",
      "claims": [
        "c10"
      ]
    },
    {
      "text": "Кривая роста монотонно возрастает от начала координат.",
      "claims": [
        "c11"
      ]
    },
    {
      "text": "Форма кривой имеет выпуклость вверх, что означает замедление роста.",
      "claims": [
        "c12"
      ]
    },
    {
      "text": "Характер роста близок к корневой или логарифмической зависимости.",
      "claims": [
        "c13"
      ]
    }
  ],
  "steps": [
    {
      "text": "1. Зафиксировать постоянство забойного давления p_c.",
      "claims": [
        "c4"
      ]
    },
    {
      "text": "2. Определить безразмерное время t·fo.",
      "claims": [
        "c9"
      ]
    },
    {
      "text": "3. По графику найти соответствующее значение R(t)/r_c.",
      "claims": [
        "c10"
      ]
    },
    {
      "text": "4. Умножить на r_c для получения физического радиуса.",
      "claims": [
        "c8"
      ]
    }
  ],
  "examples": [],
  "numbers": [
    {
      "text": "На графике ось Y достигает 8·10³.",
      "claims": [
        "c14"
      ]
    },
    {
      "text": "Ось X имеет деления до 2·10⁻⁷.",
      "claims": [
        "c15"
      ]
    },
    {
      "text": "При t·fo = 0,5 значение R(t)/r_c составляет примерно 4·10³.",
      "claims": [
        "c16"
      ]
    },
    {
      "text": "При t·fo = 1,0 значение R(t)/r_c составляет примерно 6·10³.",
      "claims": [
        "c17"
      ]
    }
  ],
  "formulas": [],
  "misconception": {
    "wrong": "Давление в пласте расходится с постоянной скоростью, как звук.",
    "right": [
      {
        "text": "Скорость продвижения фронта давления уменьшается со временем.",
        "claims": [
          "c12"
        ]
      }
    ]
  },
  "data_meaning": {
    "input": "Безразмерное время t·fo, характерный радиус r_c.",
    "output": "Безразмерный радиус возмущенной области R(t)/r_c.",
    "breaks": [
      {
        "text": "Метод не применим, если забойное давление не постоянно.",
        "claims": [
          "c4"
        ]
      }
    ],
    "hypotheses": [
      {
        "text": "Гипотеза: В ИТ-системах это можно моделировать как функцию затухания радиуса влияния события.",
        "claims": []
      }
    ]
  },
  "analogy": {
    "text": "Как рябь от брошенного в воду камня: первые волны быстро достигают берега, но их скорость падает по мере удаления.",
    "breaks_where": "В воде затухание обусловлено вязкостью и геометрией, в пласте — упругими свойствами и фильтрацией."
  },
  "now_practice": [],
  "layers": {
    "mechanism": [
      {
        "text": "Механизм основан на распространении упругой энергии в пласте.",
        "claims": [
          "c5"
        ]
      }
    ],
    "practice": [
      {
        "text": "Используется для оценки влияния скважины на удаленные объекты.",
        "claims": [
          "c7"
        ]
      }
    ],
    "nuances": [
      {
        "text": "Важно учитывать параметр fo, влияющий на масштаб времени.",
        "claims": [
          "c9"
        ]
      }
    ],
    "deeper": [
      {
        "text": "Форма кривой указывает на автомодельность процесса.",
        "claims": [
          "c13"
        ]
      }
    ]
  },
  "glossary": [
    {
      "term": "Фронт давления",
      "en": "Pressure front",
      "definition": "Граница между областью, где давление изменилось, и областью с исходным давлением."
    },
    {
      "term": "Возмущенная область",
      "en": "Disturbed region",
      "definition": "Зона пласта, на которую повлиял отбор жидкости."
    },
    {
      "term": "Невозмущенная область",
      "en": "Undisturbed region",
      "definition": "Зона пласта, где давление осталось неизменным."
    }
  ],
  "format_reason": "Текстовое описание с графиками, так как узел описывает динамику процесса и визуальную зависимость.",
